'use strict';
// The game scene is a projection of the same company; it owns no second economy.
function worldSnapshot6(cityName='Praha'){if(!CITIES.some(c=>c.name===cityName))throw Error('Neznámé město.');return {city:cityName,week:state.week,locations:LOCATIONS.filter(l=>l.city===cityName).map(l=>({id:l.id,name:l.name,segment:l.segment})),stores:state.stores.filter(s=>loc(s.id).city===cityName).map(s=>({id:s.id,color:brand(s.brand).color,franchise:s.franchise,quality:s.quality,served:s.last?.served||0,profit:s.last?.profit||0,appearance:cafeAppearance12(s),bakery:state.bakery5.bakeries.find(b=>b.cafe12===s.id)?.id||null})),opening:state.opening6.projects.filter(p=>p.city===cityName).map(p=>({id:p.id,location:p.location,status:p.status,kind:p.kind,phase:p.phase})),rivals:state.rivals.filter(r=>!r.bankrupt).map(r=>({id:r.id,name:r.name,locations:r.stores.filter(id=>loc(id)?.city===cityName)})),roasters:state.roasters.filter(r=>r.zone===cityName).map(r=>({id:r.id,name:r.name})),bakeries:state.bakery5.bakeries.filter(b=>b.city===cityName).map(b=>({id:b.id,name:b.name,cafe:b.cafe12||null})),offices:cityName==='Praha'?state.offices.map(o=>({id:o.id,name:o.name})):[],warehouses:state.warehouses.filter(w=>w.zone===cityName).map(w=>({id:w.id,name:w.name})),estates:cityName==='Praha'?state.estates.map(e=>({id:e.id,name:e.name,country:e.country,origin:e.origin})):[],vehicles:state.foodTrade9.vehicles.filter(v=>v.city===cityName).map(v=>({id:v.id,name:v.name,cold:FOOD_VEHICLES9[v.type].cold,driver:v.driver?.name||null,routeEnabled:state.foodTrade9.routes.some(r=>r.vehicle===v.id&&r.enabled),lastUnits:(state.foodTrade9.history.at(-1)?.routes||[]).filter(r=>r.vehicle===v.id).reduce((n,r)=>n+r.units,0)}))};}
function worldCafeSnapshot6(id,day=0,slot=0,editing=false){
 const s=state.stores.find(s=>s.id===id);
 if(!s||!Number.isInteger(day)||day<0||day>5||!Number.isInteger(slot)||slot<0||slot>71)throw Error('Vyber vlastní provoz a skutečný čas dne.');
 const r=editing?null:s.daily.last,frame=r?.days[day]?.timeline[slot]?cloneStudio5(r.days[day].timeline[slot]):null;
 const floor=JSON.parse(JSON.stringify(r?.floorSnapshot||s.floor)),period=Math.min(2,Math.floor(slot/24));
 if(frame&&s.food5?.last?.week===r.week){const fd=s.food5.last.days[day];frame.foodMissing9=fd?allocate5(fd.lost,r.days[day].timeline.map(p=>p.served))[slot]||0:0;}
 const crew=(r?.crewRoster?.[day]?.[period]||[]).slice(0,frame?.workers||0).map(p=>({id:p.pid,name:p.name}));
 return {id,appearance:cloneStudio5(cafeAppearance12(s)),bakery:state.bakery5.bakeries.find(b=>b.cafe12===s.id)?worldAssetSnapshot12('bakery',state.bakery5.bakeries.find(b=>b.cafe12===s.id).id):null,week:r?.week||null,day,slot:frame?JSON.parse(JSON.stringify(frame)):null,floor,crew,navigation:floorInfo5(floor,r?.floor.seats??s.seats),routes9:floorRoutes9(floor,r?.floor.seats??s.seats),quality:s.quality};
}
function worldDraftMove6(design,itemId,x,y){if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||x>7||y<0||y>5)throw Error('Vyber políčko uvnitř kavárny.');const d=cloneStudio5(design),item=d.floor.items.find(i=>i.id===itemId);if(!item)throw Error('Nejdřív vyber nábytek nebo stanici.');Object.assign(item,{x,y});return d;}
function worldDraftAdd6(design,kind,x,y){if(!Object.hasOwn(FURNITURE5,kind)||!Number.isInteger(x)||!Number.isInteger(y)||x<0||x>7||y<0||y>5)throw Error('Vyber stolek nebo barové místo a platné políčko.');const d=cloneStudio5(design);if(d.floor.items.length>=30)throw Error('V kavárně je nejvýše třicet prvků.');let i=1;while(d.floor.items.some(p=>p.id===kind+'-draft-'+i))i++;d.floor.items.push({id:kind+'-draft-'+i,kind,x,y});return d;}
function worldDraftRemove6(design,itemId){const d=cloneStudio5(design),item=d.floor.items.find(i=>i.id===itemId);if(!item||!Object.hasOwn(FURNITURE5,item.kind))throw Error('Povinné pracovní stanice se neodstraňují; vyber stůl nebo barové místo.');d.floor.items=d.floor.items.filter(i=>i.id!==itemId);return d;}
function worldDesignQuote6(id,design){const q=designQuote5(id,design);return {...q,week:state.week,cash:state.cash};}
function worldApplyDesign6(id,design,expected){guard();const q=worldDesignQuote6(id,design);if(expected&&JSON.stringify(expected)!==JSON.stringify(q))throw Error('Cena, provoz nebo hotovost se změnily. Obnov nabídku přestavby.');return planScope6('expansion','Prostorová přestavba kavárny',()=>applyDesign5(id,design,designQuote5(id,design)));}
function worldEquipmentQuote6(id,key,model){return {...equipmentQuote5(id,key,model),cash:state.cash,week:state.week};}
function worldBuyEquipment6(id,key,model,expected){const q=worldEquipmentQuote6(id,key,model);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Vybavení nebo hotovost se změnily. Prověř nabídku znovu.');return buyEquipmentModel5(id,key,model,equipmentQuote5(id,key,model));}
function worldServiceQuote6(id,key){const s=state.stores.find(s=>s.id===id),item=s?.equipment[key];if(!item||s.franchise)throw Error('Vyber své instalované zařízení.');return {id,key,model:item.model||'standard',condition:item.condition,cost:round(equipmentSpec5(key,item).cost*.08),cash:state.cash,week:state.week};}
function worldServiceEquipment6(id,key,expected){const q=worldServiceQuote6(id,key);if(q.condition>=100)throw Error('Zařízení je v plném stavu.');if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Stav nebo cena se změnily. Prověř servis znovu.');return serviceEquipment(id,key);}

// Physical extensions preserve the original production, staff, stock and accounting.
function worldAsset12(kind,id){return ({bakery:state.bakery5.bakeries,roaster:state.roasters,hq:state.offices,estate:state.estates,warehouse:state.warehouses}[kind]||[]).find(x=>x.id===id);}
function worldAssetSnapshot12(kind,id){const a=worldAsset12(kind,id);if(!a)throw Error('Vyber vlastní provoz.');const common={kind,id,name:a.name,condition:a.condition??100,staff:a.staff||0,last:a.last?cloneStudio5(a.last):null};if(kind==='bakery')return {...common,city:a.city,capacity:bakeryCapacity5(a),shifts:a.shifts,raw:a.raw.reduce((n,l)=>n+l.kg,0),recipes:state.bakery5.recipes.map(r=>({id:r.id,name:r.name})),cafe:a.cafe12||null};if(kind==='hq')return {...common,seats:a.seats,used:usedSeats(),departments:cloneStudio5(state.departments),projects:cloneStudio5(state.projects),board:proposal('expansion').votes.map(p=>({name:p.name,yes:p.yes}))};if(kind==='estate')return {...common,country:a.country,origin:a.origin,cycle:a.cycle,period:a.period,health:a.health,hectares:a.hectares,irrigation:a.irrigation,method:a.method,craft:cloneStudio5(a.craft5||{variety:"standard",process:"standard",hours:0,facilities:["standard"]})};if(kind==='roaster')return {...common,city:a.zone,capacity:roasterCapacity(a),shifts:a.shifts};return {...common,city:a.zone,capacity:a.capacity};}
function worldBakeryLinkQuote12(location,bakery){const s=state.stores.find(s=>s.id===location&&!s.franchise),b=bakeryById5(bakery);if(!s||!b||b.city!==loc(location).city)throw Error('Připoj vlastní pekárnu ve stejném městě.');if(b.cafe12||state.bakery5.bakeries.some(x=>x.cafe12===location))throw Error('Kavárna nebo pekárna už má přístavbu.');return {location,bakery,city:b.city,cost:68000,week:state.week,cash:state.cash};}
function worldLinkBakery12(location,bakery,expected){guard();const q=worldBakeryLinkQuote12(location,bakery);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Přístavba nebo hotovost se změnily. Prověř nabídku znovu.');if(state.founderShare<50&&state.expansionBudget<q.cost)throw Error('Přístavba potřebuje expanzní mandát boardu.');spend(q.cost);if(state.founderShare<50)state.expansionBudget-=q.cost;const b=bakeryById5(bakery);b.cafe12=location;b.extensionCost12=q.cost;log('Pekárna připojena: '+loc(location).name,money(q.cost)+' za přístavbu. Výrobu a odběry dál řídí skutečná pekárna.');}
const WORLD_VALUE12=companyValue;companyValue=function(...args){return WORLD_VALUE12(...args)+state.stores.reduce((n,s)=>n+CAFE_STYLES12[cafeAppearance12(s).style].cost+(cafeAppearance12(s).terrace?45000:0),0)+state.bakery5.bakeries.reduce((n,b)=>n+(b.extensionCost12||0),0);};
const WORLD_VALIDATE12=validateSave;validateSave=function(input){const v=WORLD_VALIDATE12(input),used=new Set();for(const s of v.stores)if(s.appearance&&(!Object.hasOwn(CAFE_STYLES12,s.appearance.style)||typeof s.appearance.terrace!=='boolean'))throw Error('Neplatný vzhled kavárny.');for(const d of v.studio5.designs)designInfo5(d.design);for(const b of v.bakery5.bakeries){if(b.cafe12===undefined){if(b.extensionCost12!==undefined)throw Error("Přístavba potřebuje propojenou kavárnu.");continue;}const s=v.stores.find(s=>s.id===b.cafe12&&!s.franchise);if(!s||loc(s.id).city!==b.city||used.has(s.id)||b.extensionCost12!==68000)throw Error('Neplatné propojení pekárny a kavárny.');used.add(s.id);}return v;};

function worldDepartmentQuote12(key){const d=DEPARTMENTS[key];if(!d)throw Error('Vyber oddělení.');return {key,count:state.departments[key],seats:officeSeats(),used:usedSeats(),cash:state.cash,week:state.week,cost:8000,wage:d.salary};}
function worldHireDepartment12(key,expected){const q=worldDepartmentQuote12(key);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Oddělení nebo rozpočet se změnily. Obnov nabídku.');return setDepartment(key,q.count+1);}
